{"implementation": "def solve(case):
    payload = case["payload"]
    segments = payload["segments"]
    budget = payload["budget"]

    # Start by assigning each segment its minimum allocation
    allocation = {seg["name"]: seg["minimum"] for seg in segments}
    remaining = budget - sum(seg["minimum"] for seg in segments)

    if remaining < 0:
        # Infeasible; return minimums as best effort
        return {"allocation": allocation}

    # Greedily assign remaining budget to segments in descending importance order.
    # Ties broken by segment name (lexicographic) for determinism.
    sorted_segs = sorted(segments, key=lambda s: (-s["importance"], s["name"]))

    for seg in sorted_segs:
        if remaining <= 0:
            break
        name = seg["name"]
        headroom = seg["capacity"] - allocation[name]
        add = min(headroom, remaining)
        allocation[name] += add
        remaining -= add

    return {"allocation": allocation}
"}
